// ----------------------------------------------------------------------------
// Tests_Recorded.js - auto-generated by ActionScriptQA script recorder (F1)
// Evidence CSV: evidence/<GetNameScript()>_<datetime>.csv
// Optional ListTest: <GetNameScript()>_ListTest.json (loaded if present).
// App launch: EnsureApplication_<app>() in main() before that app's tests.
// New recording sessions append function Recorded_NNN() and refresh the entry point.
// ----------------------------------------------------------------------------

var __qa_application_ready = {};

function WaitWindow(appname, windowtitle, timeoutms)
{
  var outx = { value: 0 };
  var outy = { value: 0 };
  var waited = 0;
  while(waited < timeoutms)
    {
      Sleep(500);
      waited = waited + 500;
      if(Screen_GetPosXY(appname, windowtitle, outx, outy) == 0) return true;
    }
  return false;
}

function ScriptBaseName(scriptname)
{
  var base = scriptname;
  var dot  = -1;
  if(base == "" || base == null || base == undefined) base = GetNameScript();
  dot = base.indexOf(".");
  if(dot >= 0) base = base.substring(0, dot);
  return base;
}

function ListTestFileName(scriptname)
{
  return ScriptBaseName(scriptname) + "_ListTest.json";
}

function EvidenceFileName(scriptname)
{
  return ScriptBaseName(scriptname) + "_" + FileCSV_GetShortDateTime() + ".csv";
}

function EvidenceStart(scriptname)
{
  var dir  = GetPathScript() + "evidence";
  var path = dir + "\\" + EvidenceFileName(scriptname);
  MakeDir(dir);
  if(!FileCSV_Create(path)) return false;
  if(!FileCSV_SetHeader("ID", "Description", "Result")) return false;
  if(!FileCSV_Save()) return false;
  return true;
}

function EvidenceAdd(id, description, result)
{
  var idstr = "";
  if(id !== "" && id !== null && id !== undefined) idstr = "" + (id | 0);
  return FileCSV_AddRecord(idstr, description, result);
}

function EvidenceEnd()
{
  return FileCSV_Close();
}

function EnsureApplication_chrome_exe()
{
  var appname     = "chrome.exe";
  var apppath     = "C:/Program Files/Google/Chrome/Application/chrome.exe";
  var windowtitle     = "Google Chrome";
  // Browser detected: URL cannot be captured - edit this value before running.
  var url         = "https://www.genframework.com/";
  var key         = appname;

  // Already prepared in this script run: only restore focus.
  if(__qa_application_ready[key])
    {
      Screen_SetFocus(appname, windowtitle);
      Sleep(200);
      return true;
    }

  if(WaitWindow(appname, windowtitle, 1500))
    {
      Console_Printf("[EnsureApplication] Already running: %s / %s\n", appname, windowtitle);
    }
   else
    {
      if(!OpenURL(url))
        {
          Console_Printf("[EnsureApplication] FAIL OpenURL %s\n", url);
          return false;
        }

      if(!WaitWindow(appname, windowtitle, 30000))
        {
          Console_Printf("[EnsureApplication] FAIL window not found: %s\n", windowtitle);
          TerminateAplication(appname);
          return false;
        }

      Console_Printf("[EnsureApplication] Opened URL %s\n", url);
    }

  Screen_SetFocus(appname, windowtitle);
  Sleep(300);
  __qa_application_ready[key] = true;
  Console_Printf("[EnsureApplication] Ready: %s / %s\n", appname, windowtitle);
  return true;
}

function Recorded_001()
{
  var scriptname  = GetNameScript();
  var session     = "Recorded_001";
  var appname     = "chrome.exe";
  var apppath     = "C:/Program Files/Google/Chrome/Application/chrome.exe";
  var windowtitle     = "Google Chrome";
  var outx = { value: 0 };
  var outy = { value: 0 };
  var i = 0;
  var status = 1;
  var stepresult = "PASS";
  var stepdesc = "";
  var catalogpath = "";
  var listloaded = false;

  Console_Printf("[%s] Start %s\n", scriptname, session);

  if(!EvidenceStart(scriptname))
    {
      Console_Printf("[%s] FAIL EvidenceStart/FileCSV\n", scriptname);
      return;
    }
  Console_Printf("[%s] Evidence CSV %s\n", scriptname, FileCSV_GetPath());

  catalogpath = GetPathScript() + ListTestFileName(scriptname);
  if(IsItExists(catalogpath))
    {
      if(TraceTests_Load(catalogpath))
        {
          listloaded = true;
          EvidenceAdd("", "TraceTests_Load", "PASS");
          Console_Printf("[%s] ListTest loaded %s\n", scriptname, catalogpath);
        }
       else
        {
          EvidenceAdd("", "TraceTests_Load", "FAIL");
          Console_Printf("[%s] FAIL TraceTests_Load %s\n", scriptname, catalogpath);
        }
    }
   else
    {
      EvidenceAdd("", "TraceTests_Load", "SKIP");
      Console_Printf("[%s] ListTest not found (optional) %s\n", scriptname, catalogpath);
    }

  // Application is started/focused from main() via EnsureApplication_<app>() before this test.
  Screen_SetBmpFindCFG(12, 40);
  Sleep(300);

  var actions = [
    { type: "click", bmp: "rec_001.png", x: 727, y: 136 },
    { type: "click", bmp: "rec_002.png", x: 820, y: 132 },
    { type: "click", bmp: "rec_003.png", x: 859, y: 13 },
    { type: "click", bmp: "rec_004.png", x: 885, y: 137 },
    { type: "click", bmp: "rec_005.png", x: 964, y: 134 }
  ];

  for(i = 0; i < actions.length; i++)
    {
      Screen_SetFocus(appname, windowtitle);
      Sleep(80);
      stepresult = "PASS";
      stepdesc = actions[i].type;

      if(actions[i].type == "click")
        {
          outx = { value: 0 };
          outy = { value: 0 };
          stepdesc = "click " + actions[i].bmp;
          status = Screen_GetPosXY(appname, windowtitle, actions[i].bmp, outx, outy);
          if(status != 0)
            {
              var winx = { value: 0 };
              var winy = { value: 0 };
              if(Screen_GetPosXY(appname, windowtitle, winx, winy) == 0)
                {
                  outx.value = winx.value + actions[i].x;
                  outy.value = winy.value + actions[i].y;
                  status = 0;
                }
            }
          if(status == 0)
            {
              InpSim_Mouse_Click(outx.value, outy.value);
              Console_Printf("[%s] Click %s at %d,%d\n", scriptname, actions[i].bmp, outx.value, outy.value);
              Sleep(400);
            }
           else
            {
              stepresult = "FAIL";
              Console_Printf("[%s] FAIL find %s\n", scriptname, actions[i].bmp);
            }
        }
      else if(actions[i].type == "wait")
        {
          stepdesc = "wait " + actions[i].bmp;
          if(Screen_WaitBitmap(appname, windowtitle, actions[i].bmp, actions[i].timeoutms, actions[i].intervalms))
            {
              Console_Printf("[%s] PASS wait %s\n", scriptname, actions[i].bmp);
            }
           else
            {
              stepresult = "FAIL";
              Console_Printf("[%s] FAIL wait %s (timeout)\n", scriptname, actions[i].bmp);
            }
        }
      else if(actions[i].type == "text")
        {
          stepdesc = "text";
          InpSim_Key_ClickByText(actions[i].value, 40);
          Console_Printf("[%s] Type text (%d chars)\n", scriptname, actions[i].value.length);
          Sleep(200);
        }
      else if(actions[i].type == "key")
        {
          stepdesc = "key " + actions[i].value;
          InpSim_Key_ClickByLiteral(actions[i].value, 40);
          Console_Printf("[%s] Key %s\n", scriptname, actions[i].value);
          Sleep(200);
        }

      EvidenceAdd(i + 1, stepdesc, stepresult);
    }

  if(listloaded) TraceTests_DeleteAll();
  EvidenceEnd();
  Console_Printf("[%s] End %s\n", scriptname, session);
}

function main()
{
  if(!EnsureApplication_chrome_exe()) return;
  Recorded_001();
}
